    t[62331] = { name = "Скалка Елементію", fen = "Raw Elementium pieces. Very valuable. Covered in spider excretions.", fua = "Сирі шматки елементію. Дуже цінні. Вкриті павучими виділеннями." }
    t[62332] = { name = "Відзнака Драконячої Пащі", fen = "Carved out of dragons' teeth and dyed in black blood.", fua = "Вирізана з драконячих зубів і пофарбована чорною кров'ю." }
    t[62348] = { name = "Перстень-Печатка Рівноваги Террата", fen = "As the earth stills, the din quiets, and your focus sharpens, strike true. -Terrath the Steady", fua = "Коли земля затихає, гамір змовкає, а твоя зосередженість загострюється — бий влучно. -Террат Незрушний" }
    t[62350] = { name = "Перстень Руйнування Горсіка", fen = "The earth begins to rumble and your foes begin to tremble. You come, and destruction comes with you. -Gorsik the Tumultuous", fua = "Земля починає гриміти, а вороги — тремтіти. Ти приходиш, і руйнація йде з тобою. -Горсік Бурхливий" }
    t[62351] = { name = "Перстень Рішучості Фелсена", fen = "Winds, earth, and storm may break upon your form, but your will alone will let you stand on. -Felsen the Enduring", fua = "Вітри, земля і буря можуть розбитися об твоє тіло, та лише твоя воля дасть тобі вистояти. -Фелсен Витривалий" }
